// JIRA-4829: Increase cache TTL to 600s for /api/v1/data and /api/v2/data endpoints
// Modify jenkins/pipeline.groovy
pipeline {
  environment {
    CACHE_TTL = '600'
    CACHE_ENDPOINTS = '/api/v1/data,/api/v2/data'
  }
  stages {
    stage('Deploy') {
      steps {
        // Apply TTL configuration to Redis cache for specified endpoints
        sh "apply-cache-config --ttl ${CACHE_TTL} --endpoints ${CACHE_ENDPOINTS}"
      }
    }
  }
}

